let transferFilters={position:'all',sort:'position',query:'',shortlistOnly:false,affordableOnly:false},recruitmentReview=null,recruitmentReturn=null,recruitmentBusy=false;
function transferCandidates(){
 const host=$('transfer-search-panel'),m=TransferPlans.search(season,transferFilters,outgoingChoices);if(!host)return m.rows.map(r=>F.market.find(p=>p.identity===r.identity));const esc=escapeText;
 host.innerHTML='<section class="transfer-search" aria-labelledby="transfer-search-title"><div class="panel-heading"><h2 id="transfer-search-title">필요한 한 명 찾기</h2><span role="status">후보 '+m.rows.length+' / '+m.total+'명 · 관심 '+m.shortlistCount+'명</span></div><div class="transfer-filter-grid"><label>포지션<select id="transfer-position">'+[['all','전체 포지션'],['GK','GK · 골키퍼'],['DEF','DEF · 수비수'],['MID','MID · 미드필더'],['FW','FW · 공격수']].map(([v,t])=>'<option value="'+v+'"'+(v===m.filters.position?' selected':'')+'>'+t+'</option>').join('')+'</select></label><label>정렬<select id="transfer-sort">'+[['position','포지션 순'],['cost','영입 지출 낮은 순'],['potential','성장 한계 높은 순'],['primary','주요 능력 높은 순']].map(([v,t])=>'<option value="'+v+'"'+(v===m.filters.sort?' selected':'')+'>'+t+'</option>').join('')+'</select></label><form id="transfer-query-form"><label>이름·유형 검색<input type="search" id="transfer-query" maxlength="60" value="'+esc(m.filters.query)+'" placeholder="선수 이름, 즉시 전력, 유망주"></label><button type="submit" class="secondary">검색</button></form></div><div class="transfer-filter-toggles"><button type="button" id="transfer-shortlist-only" aria-pressed="'+m.filters.shortlistOnly+'" class="secondary">관심 선수만</button><button type="button" id="transfer-affordable-only" aria-pressed="'+m.filters.affordableOnly+'" class="secondary">현재 자금 안에서</button><button type="button" id="transfer-filter-reset" class="text-button">필터 초기화</button></div><p>지출은 각 후보 카드에 선택한 방출 선수 기준입니다. 자금 필터는 금액만 비교하며, 주간 영입·팀 대화 제한은 후보 카드에서 확인하세요.</p>'+(m.rows.length?'':'<p class="transfer-empty" role="status">조건에 맞는 후보가 없습니다. 포지션이나 필터를 바꾸거나 관심 선수를 추가하세요.</p>')+'</section>';
 const redraw=id=>{renderMarket();$(id)?.focus({preventScroll:true});};$('transfer-position').onchange=e=>{transferFilters.position=e.target.value;redraw('transfer-position');};$('transfer-sort').onchange=e=>{transferFilters.sort=e.target.value;redraw('transfer-sort');};$('transfer-query-form').onsubmit=e=>{e.preventDefault();transferFilters.query=$('transfer-query').value;redraw('transfer-query');};$('transfer-shortlist-only').onclick=()=>{transferFilters.shortlistOnly=!transferFilters.shortlistOnly;redraw('transfer-shortlist-only');};$('transfer-affordable-only').onclick=()=>{transferFilters.affordableOnly=!transferFilters.affordableOnly;redraw('transfer-affordable-only');};$('transfer-filter-reset').onclick=()=>{transferFilters={position:'all',sort:'position',query:'',shortlistOnly:false,affordableOnly:false};redraw('transfer-position');};
 return m.rows.map(r=>F.market.find(p=>p.identity===r.identity));
}
function transferShortlistMarkup(identity){const on=!!season.transferPlans?.shortlist.includes(identity);return '<button type="button" class="secondary transfer-shortlist" data-shortlist="'+escapeText(identity)+'" aria-pressed="'+on+'">'+(on?'★ 관심 선수':'☆ 관심에 추가')+'</button>';}
function bindTransferShortlist(host){host.querySelectorAll('[data-shortlist]').forEach(button=>button.onclick=()=>{const identity=button.dataset.shortlist;action(()=>{season=TransferPlans.toggle(season,identity);state=season.match;});const next=$('market-overview').querySelector('[data-shortlist="'+identity+'"]');(next||$('transfer-shortlist-only'))?.focus({preventScroll:true});});}
function openRecruitmentReview(identity,slot){
 if(recruitmentBusy)return;const dialog=$('recruitment-dialog');if(!dialog)return;recruitmentReturn=document.activeElement;recruitmentReview=null;let error='';try{recruitmentReview=TransferPlans.preview(season,identity,slot);}catch(e){error=e.message;}const m=recruitmentReview,esc=escapeText;
 dialog.innerHTML='<div class="recruitment-head"><div><span class="eyebrow">CONTRACT REVIEW</span><h2 id="recruitment-title">'+(m?.academy?'1군 등록 최종 확인':'영입 최종 확인')+'</h2></div><button type="button" id="close-recruitment" class="secondary" aria-label="영입 검토 닫기">×</button></div><div class="recruitment-body">'+(m?'<p class="recruitment-warning"><strong>'+esc(m.outgoing.name)+'</strong> 선수가 구단을 떠납니다. 이 선수의 성장과 경험은 새 선수에게 이어지지 않습니다. 확정 전에 교환 대상을 확인하세요.</p><div class="recruitment-people"><article><span>떠나는 선수 · '+m.outgoing.pos+'</span><h3>'+esc(m.outgoing.name)+'</h3><p>주요 능력 '+m.outgoing.primary+' · 성장 한계 '+m.outgoing.potential+'</p><small>누적 출전 경험 '+m.outgoing.xp.toLocaleString('ko-KR')+'분</small></article><article><span>합류하는 선수 · '+m.incoming.pos+'</span><h3>'+esc(m.incoming.name)+'</h3><p>주요 능력 '+m.incoming.primary+' · 성장 한계 '+m.incoming.potential+'</p><small>출전 경험 0 · 체력 100</small></article></div><dl class="recruitment-terms"><div><dt>'+(m.quote.cost<0?'구단에 돌아오는 자금':'영입 지출 · 수수료 포함')+'</dt><dd>'+moneyLabel(m.quote.cost)+'</dd></div><div><dt>영입 후 자금</dt><dd>'+moneyLabel(m.quote.balanceAfter)+'</dd></div><div><dt>선수 주급 변화</dt><dd>'+signedMoney(m.quote.wageChange)+'</dd></div></dl><p class="recruitment-note">이번 주 영입 기회 1회를 사용합니다. 새 선수는 '+(m.starting?'선발에':'벤치에')+' 등록됩니다.'+(m.lineupChanged?' 출전 가능 인원을 맞추며 선발이 조정됩니다.':'')+'</p><div class="recruitment-actions"><button type="button" id="cancel-recruitment" class="secondary">다시 비교하기</button><button type="button" id="confirm-recruitment" class="primary">이 조건으로 '+(m.academy?'1군 등록':'영입')+' 확정</button></div>':'<p class="recruitment-warning">'+esc(error)+'</p>')+'<p id="recruitment-status" role="status" aria-live="polite"></p></div>';
 const close=()=>{if(recruitmentBusy)return;dialog.close();recruitmentReview=null;recruitmentReturn?.focus?.({preventScroll:true});};$('close-recruitment').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};if(m){$('cancel-recruitment').onclick=close;$('confirm-recruitment').onclick=confirmRecruitmentReview;}if(!dialog.open)dialog.showModal();$('close-recruitment').focus({preventScroll:true});
}
function confirmRecruitmentReview(){
 if(recruitmentBusy||!recruitmentReview)return;const m=recruitmentReview,dialog=$('recruitment-dialog'),button=$('confirm-recruitment');recruitmentBusy=true;button.disabled=true;$('cancel-recruitment').disabled=true;$('close-recruitment').disabled=true;$('recruitment-status').textContent='계약을 등록하고 구단을 저장하는 중…';dialog.setAttribute('aria-busy','true');
 requestAnimationFrame(()=>setTimeout(()=>{try{const next=TransferPlans.confirm(season,m.identity,m.slot,m.fingerprint);season=next;state=season.match;selected=null;save();recruitmentReview=null;dialog.close();render();$('notice').textContent=m.incoming.name+' '+(m.academy?'1군 등록':'영입')+' 완료 · '+m.outgoing.name+' 이적'+(canSave?'':' · 저장 공간을 확인해 주세요.');$('notice').hidden=false;const control=$(view+'-pane')?.querySelector('[data-player-detail="'+m.identity+'"]');(control||$('transfer-position')||recruitmentReturn)?.focus?.({preventScroll:true});}catch(e){$('recruitment-status').textContent=e.message;button.disabled=true;$('cancel-recruitment').disabled=false;$('close-recruitment').disabled=false;}finally{recruitmentBusy=false;dialog.removeAttribute('aria-busy');}},0));
}
